import React, { useState, useEffect, useContext } from 'react';
import { observer } from 'mobx-react-lite';
import { Context } from '../index';
import { Modal, Button, ListGroup, Form, Row, Col, Badge, Spinner, Alert } from 'react-bootstrap';
import { http } from '../http';
import '../css/components/MessageModal.css';

const MessageModal = observer(() => {
    const { message, user } = useContext(Context);
    const [newMessage, setNewMessage] = useState('');
    const [loading, setLoading] = useState(false);
    const [chatsLoading, setChatsLoading] = useState(false);
    const [messagesLoading, setMessagesLoading] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        if (message.isModalOpen && user.isAuth) {
            loadChats();
        } else {
            // Сбрасываем состояние при закрытии модалки
            message.setActiveChat(null);
            message.setMessages([]);
            setNewMessage('');
            setError('');
        }
    }, [message.isModalOpen, user.isAuth]);

    const loadChats = async () => {
        if (!user.user?.id) {
            setError('Пользователь не авторизован');
            return;
        }

        setChatsLoading(true);
        setError('');
        try {
            const response = await http.get(`/api/message/chats/${user.user.id}`);
            if (response.data) {
                message.setChats(response.data);
                
                // Подсчет непрочитанных сообщений
                const unreadCount = response.data.reduce((total, chat) => total + (chat.unreadCount || 0), 0);
                message.setUnreadCount(unreadCount);
            }
        } catch (error) {
            console.error('Ошибка при загрузке чатов:', error);
            setError('Не удалось загрузить чаты');
        } finally {
            setChatsLoading(false);
        }
    };

    const loadMessages = async (otherUser, product = null) => {
        if (!user.user?.id || !otherUser?.id) {
            setError('Неверные данные пользователя');
            return;
        }

        setMessagesLoading(true);
        setError('');
        try {
            // Формируем URL в зависимости от наличия продукта
            let url = `/api/message/messages/${user.user.id}/${otherUser.id}`;
            if (product && product.id) {
                url += `/${product.id}`;
            } else {
                url += '/0'; // Используем 0 для чатов без продукта
            }

            const response = await http.get(url);
            if (response.data) {
                message.setMessages(response.data);
            }
        } catch (error) {
            console.error('Ошибка при загрузке сообщений:', error);
            setError('Не удалось загрузить сообщения');
        } finally {
            setMessagesLoading(false);
        }
    };

    const sendMessage = async () => {
        if (!newMessage.trim() || !message.activeChat) return;
        if (!user.user?.id || !message.activeChat.otherUser?.id) {
            setError('Неверные данные для отправки сообщения');
            return;
        }

        setLoading(true);
        setError('');
        try {
            const messageData = {
                sender_id: user.user.id,
                receiver_id: message.activeChat.otherUser.id,
                product_id: message.activeChat.product?.id || null,
                message: newMessage.trim()
            };

            const response = await http.post('/api/message/send', messageData);
            if (response.data) {
                message.addMessage(response.data);
                setNewMessage('');
                
                // Обновляем список чатов
                await loadChats();
            }
        } catch (error) {
            console.error('Ошибка при отправке сообщения:', error);
            setError('Не удалось отправить сообщение');
        } finally {
            setLoading(false);
        }
    };

    const handleKeyPress = (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            sendMessage();
        }
    };

    const formatMessageTime = (timestamp) => {
        if (!timestamp) return '';
        const date = new Date(timestamp);
        return date.toLocaleTimeString('ru-RU', { 
            hour: '2-digit', 
            minute: '2-digit' 
        });
    };

    const formatChatTime = (timestamp) => {
        if (!timestamp) return '';
        const date = new Date(timestamp);
        const now = new Date();
        const diffDays = Math.floor((now - date) / (1000 * 60 * 60 * 24));
        
        if (diffDays === 0) {
            return 'Сегодня';
        } else if (diffDays === 1) {
            return 'Вчера';
        } else if (diffDays < 7) {
            return `${diffDays} дн. назад`;
        } else {
            return date.toLocaleDateString('ru-RU');
        }
    };

    const truncateMessage = (text, maxLength = 30) => {
        if (!text) return '';
        return text.length > maxLength ? text.substring(0, maxLength) + '...' : text;
    };

    const handleChatSelect = (chat) => {
        if (chat.otherUser && chat.otherUser.id) {
            loadMessages(chat.otherUser, chat.product);
        }
    };

    return (
        <Modal 
            show={message.isModalOpen} 
            onHide={() => message.setIsModalOpen(false)}
            size="lg"
            centered
            dialogClassName="message-modal"
        >
            <Modal.Header closeButton>
                <Modal.Title>💬 Мои сообщения</Modal.Title>
                {message.unreadCount > 0 && (
                    <Badge bg="danger" className="ms-2">
                        {message.unreadCount}
                    </Badge>
                )}
            </Modal.Header>
            
            <Modal.Body className="message-modal-body">
                {error && (
                    <Alert variant="danger" className="mb-2">
                        {error}
                    </Alert>
                )}
                
                <Row>
                    {/* Список чатов */}
                    <Col md={4} className="chats-sidebar">
                        <div className="chats-header">
                            <h6>Чаты</h6>
                            <Button 
                                variant="outline-primary" 
                                size="sm" 
                                onClick={loadChats}
                                disabled={chatsLoading}
                            >
                                {chatsLoading ? <Spinner animation="border" size="sm" /> : 'Обновить'}
                            </Button>
                        </div>
                        
                        {chatsLoading ? (
                            <div className="text-center p-4">
                                <Spinner animation="border" variant="primary" />
                                <div className="mt-2">Загрузка чатов...</div>
                            </div>
                        ) : (
                            <ListGroup variant="flush" className="chats-list">
                                {message.chats && message.chats.length > 0 ? (
                                    message.chats.map((chat, index) => (
                                        <ListGroup.Item
                                            key={chat.otherUser?.id || index}
                                            action
                                            active={message.activeChat?.otherUser?.id === chat.otherUser?.id}
                                            onClick={() => handleChatSelect(chat)}
                                            className="chat-item"
                                        >
                                            <div className="chat-info">
                                                <div className="d-flex justify-content-between align-items-start">
                                                    <strong className="chat-username">
                                                        {chat.otherUser?.username || 'Неизвестный пользователь'}
                                                    </strong>
                                                    {chat.unreadCount > 0 && (
                                                        <Badge bg="danger" pill className="ms-2">
                                                            {chat.unreadCount}
                                                        </Badge>
                                                    )}
                                                </div>
                                                
                                                {chat.product && (
                                                    <small className="text-muted d-block product-name">
                                                        Товар: {chat.product.name}
                                                    </small>
                                                )}
                                                
                                                <small className="last-message text-muted">
                                                    {truncateMessage(chat.lastMessage)}
                                                </small>
                                                
                                                <small className="message-time d-block">
                                                    {formatChatTime(chat.lastMessageTime)}
                                                </small>
                                            </div>
                                        </ListGroup.Item>
                                    ))
                                ) : (
                                    <ListGroup.Item>
                                        <div className="text-center text-muted py-4">
                                            <div>💬</div>
                                            <div>Нет активных чатов</div>
                                            <small>Начните общение с продавцом</small>
                                        </div>
                                    </ListGroup.Item>
                                )}
                            </ListGroup>
                        )}
                    </Col>

                    {/* Область сообщений */}
                    <Col md={8} className="messages-area">
                        {message.activeChat ? (
                            <>
                                <div className="chat-header">
                                    <div>
                                        <h6 className="mb-0">
                                            Чат с {message.activeChat.otherUser?.username || 'Неизвестный пользователь'}
                                            {message.activeChat.product && (
                                                <Badge bg="secondary" className="ms-2">
                                                    {message.activeChat.product.name}
                                                </Badge>
                                            )}
                                        </h6>
                                        <small className="text-muted">
                                            {message.activeChat.otherUser?.role === 'SELLER' ? 'Продавец' : 
                                             message.activeChat.otherUser?.role === 'ADMIN' ? 'Администратор' : 'Покупатель'}
                                        </small>
                                    </div>
                                </div>
                                
                                <div className="messages-list">
                                    {messagesLoading ? (
                                        <div className="text-center p-4">
                                            <Spinner animation="border" variant="primary" />
                                            <div className="mt-2">Загрузка сообщений...</div>
                                        </div>
                                    ) : message.messages && message.messages.length > 0 ? (
                                        message.messages.map((msg) => (
                                            <div
                                                key={msg.id}
                                                className={`message-bubble ${
                                                    msg.sender_id === user.user.id ? 'sent' : 'received'
                                                }`}
                                            >
                                                <div className="message-content">
                                                    {msg.message}
                                                </div>
                                                <small className="message-time">
                                                    {formatMessageTime(msg.timestamp)}
                                                    {!msg.is_read && msg.sender_id === user.user.id && (
                                                        <span className="ms-1">✓</span>
                                                    )}
                                                </small>
                                            </div>
                                        ))
                                    ) : (
                                        <div className="text-center text-muted py-4">
                                            <div>💭</div>
                                            <div>Нет сообщений</div>
                                            <small>Начните диалог первым</small>
                                        </div>
                                    )}
                                </div>

                                <div className="message-input">
                                    <Form.Group>
                                        <Form.Control
                                            as="textarea"
                                            rows={2}
                                            value={newMessage}
                                            onChange={(e) => setNewMessage(e.target.value)}
                                            onKeyPress={handleKeyPress}
                                            placeholder="Введите сообщение..."
                                            disabled={loading || messagesLoading}
                                            maxLength={1000}
                                        />
                                        <Form.Text className="text-muted">
                                            {newMessage.length}/1000 символов
                                        </Form.Text>
                                    </Form.Group>
                                    <div className="d-flex justify-content-between align-items-center mt-2">
                                        <small className="text-muted">
                                            Нажмите Enter для отправки
                                        </small>
                                        <Button
                                            variant="primary"
                                            onClick={sendMessage}
                                            disabled={!newMessage.trim() || loading || messagesLoading}
                                            size="sm"
                                        >
                                            {loading ? (
                                                <>
                                                    <Spinner animation="border" size="sm" className="me-2" />
                                                    Отправка...
                                                </>
                                            ) : (
                                                'Отправить'
                                            )}
                                        </Button>
                                    </div>
                                </div>
                            </>
                        ) : (
                            <div className="text-center text-muted select-chat-prompt">
                                <div className="py-5">
                                    <div style={{ fontSize: '3rem' }}>💬</div>
                                    <h6>Выберите чат для начала общения</h6>
                                    <small>или начните новый диалог с продавцом</small>
                                </div>
                            </div>
                        )}
                    </Col>
                </Row>
            </Modal.Body>
        </Modal>
    );
});

export default MessageModal;
